/* ===== x15_v56.js ===== */
/* ============================================================================
   v5.6 LAYER 15 — review fixes and the two commercial refinements, plus cash handling.
   A. Door sales create a ticket sale (review defect 1)
   B. Retention is a control, not a label (review defect 2)
   C. Allocation mismatch is an exception, never a silent patch (review defect 3)
   D. Vendor reliability beside the next quote; "hire again?" at close-out
   E. Close-out → proposed price-book changes, approved one by one by the owner
   F. Cash handling: cash book, cash vouchers, Section 269ST and 40A(3) warnings,
      unregistered-vendor consequences. Cash is recorded in full; nothing is kept off the books.
   ============================================================================ */
coll('rateProposals','cashMoves','cashVouchers');
MIGRATIONS.push({from:55,to:56,note:'v5.5 → v5.6: rate proposals, cash book moves and cash vouchers added empty; cash rules defaulted on the company (verify limits with your CA); vendor rehire answers added empty.',up(o){ensureCollections(o);o.company=o.company||{};if(!o.company.cashRules)o.company.cashRules=defaultCashRules();(o.vendors||[]).forEach(v=>{if(!v.rehire)v.rehire=[]});return o}});
function defaultCashRules(){return {s269Paise:20000000,s40a3Paise:1000000,voucherPrefix:'CV/26-27/',voucherSeq:0,openingPaise:0,openingDate:'2026-04-01'}}
function cashRules(){if(!S.company.cashRules)S.company.cashRules=defaultCashRules();return S.company.cashRules}
/* persistent capture-phase guard on a modal form: fn(evt) may call block(evt) to stop the base handler */
function guardSubmit(f,fn){const h=e=>{if(!document.contains(f)){document.removeEventListener('submit',h,true);return}if(e.target===f)fn(e)};document.addEventListener('submit',h,true)}
const blockSubmit=e=>{e.preventDefault();e.stopPropagation();e.stopImmediatePropagation()};
var afterSave=fn=>setTimeout(()=>{if(modalClosed())fn()},0);
const isOwner=()=>{if(typeof currentSession==='function'&&!currentSession())return false;const u=me();return !!u&&u.role==='owner'};

/* ---------- A. Door sales ---------- */
function registerDelegate(e,d){if(S.delegates.some(x=>x.eventId===e.id&&x.email&&x.email.toLowerCase()===(d.email||'').toLowerCase()&&x.status!=='cancelled'))return {dup:true};const tt=S.ticketTypes.find(t=>t.id===d.ticketTypeId);if(tt&&tt.sold>=tt.qty)return {soldOut:true};const paidNow=!!d.paidNow;const mode=d.mode||'cash';delete d.paidNow;delete d.mode;const rec=stamp(Object.assign({id:uid(),eventId:e.id,status:'registered',paidPaise:0,token:Math.random().toString(36).slice(2,10)},d));S.delegates.push(rec);let sale=null;if(tt){tt.sold=(tt.sold||0)+1;if(tt.pricePaise>0&&!d.comp){sale=stamp({id:uid(),eventId:e.id,delegateId:rec.id,ticketTypeId:tt.id,amountPaise:tt.pricePaise,status:paidNow?'paid':'pending',date:todayStr(),paidAt:paidNow?nowISO():null,mode:paidNow?mode:null,source:d.source||'manual'});S.ticketSales.push(sale);if(paidNow){rec.paidPaise=tt.pricePaise;rec.status='confirmed';laneIncome(e,{id:sale.id,name:rec.name},'Ticket',sale.amountPaise);if(mode==='cash')cashVoucher('receipt',sale.amountPaise,{eventId:e.id,ref:'ticket:'+sale.id,party:rec.name,desc:'Ticket at the door · '+tt.name})}}}save();return {ok:true,rec,sale}}
act('delegate-add',({E})=>{const e=E();const tts=S.ticketTypes.filter(t=>t.eventId===e.id);openModal(`${hd('Delegate')}<form id="f-dl"><label for="dln">Name</label><input id="dln" required><div class="two"><div><label for="dle">Email</label><input id="dle" type="email"></div><div><label for="dlc">Company</label><input id="dlc"></div></div><label for="dlt">Ticket class</label><select id="dlt"><option value="">—</option>${tts.map(t=>`<option value="${t.id}" data-price="${t.pricePaise}">${esc(t.name)} · ${inr(t.pricePaise)}</option>`).join('')}</select><div id="dlpay" hidden><div class="note" style="margin:6px 0"><b>Paid ticket.</b> A sale record is created either way — pending until the money is recorded, so door cash never goes missing from the books.</div><label class="chk"><input type="checkbox" id="dlp"> Payment collected now (at the door)</label><div class="two" id="dlmrow" hidden><div><label for="dlm">Collected via</label>${modeSel('dlm','cash')}</div><div><label for="dlr">Reference</label><input id="dlr" placeholder="UPI ref / receipt no."></div></div><label class="chk"><input type="checkbox" id="dlcomp"> Complimentary (no sale, note why below)</label></div><label class="chk"><input type="checkbox" id="dlk"> Agreed to attendee messages</label><label for="dlnote">Note</label><input id="dlnote">${ft('Add')}</form>`);const upd=()=>{const o=F('dlt').selectedOptions[0];const price=o?parseInt(o.dataset.price||'0'):0;F('dlpay').hidden=!price;F('dlmrow').hidden=!F('dlp').checked};F('dlt').addEventListener('change',upd);F('dlp').addEventListener('change',upd);F('f-dl').addEventListener('submit',x=>{x.preventDefault();const comp=F('dlcomp').checked;if(comp&&!F('dlnote').value.trim())return toast('Say why the ticket is complimentary');const r=registerDelegate(e,{name:F('dln').value.trim(),email:F('dle').value.trim(),company:F('dlc').value.trim(),ticketTypeId:F('dlt').value||null,consent:F('dlk').checked,source:'manual',note:F('dlnote').value.trim(),comp,paidNow:F('dlp').checked&&!comp,mode:F('dlm').value});if(r.dup)return toast('This email is already registered');if(r.soldOut)return toast('That ticket class is sold out');if(r.sale&&r.sale.mode)r.sale.ref=F('dlr').value.trim();audit('create','delegates',r.rec.id,r.rec.name+(r.sale?' · ticket '+inr(r.sale.amountPaise)+' '+r.sale.status:''),e.id);save();closeModal();render();toast(r.sale?(r.sale.status==='paid'?'Delegate added · ticket sale recorded as paid':'Delegate added · ticket sale pending'):'Delegate added')})});
act('delegate-cancel',({id})=>{const d=S.delegates.find(x=>x.id===id);d.status='cancelled';d.cancelledAt=nowISO();const tt=S.ticketTypes.find(t=>t.id===d.ticketTypeId);if(tt)tt.sold=Math.max(0,(tt.sold||0)-1);const s=S.ticketSales.find(x=>x.delegateId===d.id&&x.status==='pending');if(s){s.status='cancelled';s.cancelledAt=nowISO()}const paid=S.ticketSales.find(x=>x.delegateId===d.id&&x.status==='paid');audit('update','delegates',d.id,'cancelled'+(s?' · pending sale cancelled':paid?' · paid ticket stays on record':''),d.eventId);save();render();if(paid)toast('Cancelled. The paid ticket stays on record — refund it from the ticketing card if the policy allows')});
function ticketDrift(e){return S.ticketTypes.filter(t=>t.eventId===e.id).map(t=>{const active=S.delegates.filter(d=>d.eventId===e.id&&d.ticketTypeId===t.id&&d.status!=='cancelled');const noSale=t.pricePaise>0?active.filter(d=>!d.comp&&!S.ticketSales.some(s=>s.delegateId===d.id&&s.status!=='cancelled')):[];return {t,active:active.length,noSale}}).filter(x=>x.active!==(x.t.sold||0)||x.noSale.length)}
const _ciBase=checkInvariants;checkInvariants=function(){const r=_ciBase();if(r)return r;for(const e of S.events){for(const x of ticketDrift(e)){if(x.active!==(x.t.sold||0))return `${e.name}: ticket class ${x.t.name} shows ${x.t.sold||0} sold but ${x.active} active delegate(s)`;if(x.noSale.length)return `${e.name}: ${x.noSale.length} paid-class delegate(s) without a ticket sale (${x.noSale[0].name})`}}for(const s of S.ticketSales)if(!Number.isInteger(s.amountPaise)||s.amountPaise<0)return 'ticket sale '+s.id+' invalid amount';return null};

/* ---------- B. Retention ---------- */
function retentionHeld(cmId){return sum(live(S.orders).filter(o=>o.commitmentId===cmId&&o.delivery&&o.delivery.retentionPaise>0&&!o.delivery.retentionReleasedAt),o=>o.delivery.retentionPaise)}
const _commCalcBase=commCalc;commCalc=function(c){const k=_commCalcBase(c);k.retention=retentionHeld(c.id);k.payable=Math.max(0,k.outstanding-k.retention);return k};
const _mPaymentRet=mPayment;mPayment=function(cm){_mPaymentRet(cm);const f=document.querySelector('.modal form');if(!f)return;const k=commCalc(cm);const v=vendor(cm.vendorId);const o=live(S.orders).find(x=>x.commitmentId===cm.id&&x.delivery&&x.delivery.retentionPaise>0&&!x.delivery.retentionReleasedAt);const box=document.createElement('div');box.id='retbox';if(k.retention>0){box.innerHTML=`<div class="alert" style="margin:6px 0"><b>Retention held: ${inr(k.retention)}</b> — ${esc(o.delivery.retentionReason||'no reason recorded')}. Payable now is <b class="num">${inr(k.payable)}</b>, not ${inr(Math.max(0,k.outstanding))}. Paying more releases the only leverage you have on that fault.</div><div id="retwhy" hidden><label for="retr">Why pay beyond the retention? (at least 10 characters)</label><textarea id="retr"></textarea></div>`;const pa=F('pa');if(pa&&toPaise(pa.value)>k.payable)pa.value=k.payable/100}const cashBox=document.createElement('div');cashBox.id='cashbox';f.insertBefore(box,f.querySelector('.ft'));f.insertBefore(cashBox,f.querySelector('.ft'));
  guardSubmit(f,evt=>{const amt=toPaise(F('pa').value)||0;let retReason='';if(k.retention>0&&amt>k.payable){const w=F('retwhy');if(w.hidden){w.hidden=false;F('retr').focus();toast('Say why this payment goes beyond the retention held');return blockSubmit(evt)}retReason=(F('retr').value||'').trim();if(retReason.length<10){F('retr').focus();toast('A reason of at least 10 characters is required');return blockSubmit(evt)}}
    const mode=F('pm').value;let cashAck=false;if(mode==='cash'){const r=cashRules();const sameDay=sum(live(S.payments).filter(p=>p.mode==='cash'&&p.date===F('pd').value&&(S.commitments.find(c=>c.id===p.commitmentId)||{}).vendorId===cm.vendorId),p=>p.amountPaise);if(sameDay+amt>r.s40a3Paise){const cb=F('cashbox');if(!F('cashack')){cb.innerHTML=`<div class="alert" style="margin:6px 0"><h3>Cash above ${inr(r.s40a3Paise)} in a day to one vendor</h3><p class="small">Section 40A(3): cash payments over this limit to one person in a day are not allowed as an expense for income tax (${sameDay?'already '+inr(sameDay)+' in cash today; ':''}this makes ${inr(sameDay+amt)}). The payment is recorded in full either way — this app does not hide money. Pay by bank/UPI if you still can; otherwise record it and let your CA treat it.</p><label class="chk"><input type="checkbox" id="cashack"> Record it anyway — I understand the expense may be disallowed</label></div>`;F('cashack').focus();return blockSubmit(evt)}if(!F('cashack').checked){toast('Tick the acknowledgement or change the payment mode');return blockSubmit(evt)}cashAck=true}}
    afterSave(()=>{const p=S.payments[S.payments.length-1];if(!p||p.commitmentId!==cm.id)return;let ch=false;if(retReason){p.retentionOverride=retReason;audit('override','payments',p.id,`paid ${inr(p.amountPaise)} beyond retention ${inr(k.retention)}: ${retReason}`,cm.eventId);ch=true}if(p.mode==='cash'){if(cashAck){p.s40a3Flag=true;audit('flag','payments',p.id,'cash above the 40A(3) daily limit, acknowledged',cm.eventId)}cashVoucher('payment',p.amountPaise-(p.tdsPaise||0),{eventId:cm.eventId,ref:'payment:'+p.id,party:v.name,desc:'Vendor payment · '+(cm.scope||v.name)});ch=true}if(ch)save()})})};
act('retention-release',({id})=>{const o=S.orders.find(x=>x.id===id);const cm=S.commitments.find(c=>c.id===o.commitmentId);openModal(`${hd('Release retention')}<form id="f-rr"><p class="small">${inr(o.delivery.retentionPaise)} held on ${esc(o.no)} — ${esc(o.delivery.retentionReason||'')}. Releasing it makes the full outstanding payable again.</p><label for="rrw">Why is it fixed / settled?</label><textarea id="rrw" required></textarea>${ft('Release')}</form>`);F('f-rr').addEventListener('submit',x=>{x.preventDefault();const w=F('rrw').value.trim();if(w.length<5)return toast('Say why');o.delivery.retentionReleasedAt=nowISO();o.delivery.retentionReleasedBy=UI.userId;o.delivery.retentionReleaseReason=w;touch(o);audit('update','orders',o.id,`retention ${inr(o.delivery.retentionPaise)} released: ${w}`,o.eventId);save();closeModal();render()})});
VENDOR_ROW_EXT.push((cm,e)=>{if(cm.voided||cm.status==='quote'||!seesMoney())return '';const os=live(S.orders).filter(o=>o.commitmentId===cm.id&&o.delivery&&o.delivery.retentionPaise>0);if(!os.length)return '';return os.map(o=>o.delivery.retentionReleasedAt?`<div class="meta">Retention ${inr(o.delivery.retentionPaise)} released ${fmtShort(o.delivery.retentionReleasedAt.slice(0,10))}: ${esc(o.delivery.retentionReleaseReason||'')}</div>`:`<div class="chips" style="margin-top:4px"><span class="pill warn">Retention held ${inr(o.delivery.retentionPaise)}</span><span class="small muted">${esc(o.delivery.retentionReason||'')} · payable now ${inr(commCalc(cm).payable)}</span>${can('vendors')&&!locked(e)?`<button class="btn sm" data-act="retention-release" data-id="${o.id}">Release</button>`:''}</div>`).join('')});

/* ---------- C. Allocation mismatch ---------- */
/* Rule: the recorded split is never patched. An approved change linked to the agreement adds its cost to the line the change names; if the agreement has exactly one line, to that line; otherwise it stays unplaced and counts as a mismatch. */
function allocOf(cm){if(cm.allocation&&cm.allocation.length){const out=cm.allocation.map(a=>Object.assign({},a));linkedChanges(cm.id).forEach(ch=>{const i=ch.scopeLineId?out.findIndex(a=>a.scopeLineId===ch.scopeLineId):-1;if(i>=0)out[i].amountPaise+=ch.costPaise;else if(out.length===1)out[0].amountPaise+=ch.costPaise});return out}if(cm.scopeLineIds&&cm.scopeLineIds.length){const tot=cm.agreedPaise+linkedChangeCost(cm.id);const per=Math.floor(tot/cm.scopeLineIds.length);return cm.scopeLineIds.map((id,i)=>({scopeLineId:id,amountPaise:i===cm.scopeLineIds.length-1?tot-per*(cm.scopeLineIds.length-1):per}))}return []}
function linkedChanges(cid){const cm=S.commitments.find(c=>c.id===cid);if(!cm||cm.fromChangeId)return [];return live(S.changes).filter(ch=>chApproved(ch)&&ch.commitmentId===cid&&!ch.generatedCommitmentId)}
function allocMismatch(cm){if(!(cm.allocation&&cm.allocation.length))return 0;return (cm.agreedPaise+linkedChangeCost(cm.id))-sum(allocOf(cm),a=>a.amountPaise)}
function mismatchesOf(eventId){return costComms(eventId).map(cm=>({cm,diff:allocMismatch(cm)})).filter(x=>x.diff!==0)}
const _scopeSummaryBase=scopeSummary;scopeSummary=function(e){const r=_scopeSummaryBase(e);const mm=mismatchesOf(e.id);r.mismatches=mm;r.mismatchCost=sum(mm,x=>x.diff);r.unallocCost+=r.mismatchCost;r.forecastVendors+=r.mismatchCost;return r};
const _tabScopeMm=tabScope;tabScope=function(e,c){const h=_tabScopeMm(e,c);if(!seesMoney())return h;const mm=mismatchesOf(e.id);if(!mm.length)return h;return `<div class="alert" style="margin-bottom:12px"><h3>${mm.length} vendor agreement(s) do not add up to their scope lines</h3><div class="small">The difference is counted in the forecast as unallocated — it is not hidden — but it is not on any line and it will not reach a work order until it is placed.</div>${mm.map(x=>`<div class="row between" style="margin-top:6px"><span>${esc(vendor(x.cm.vendorId).name)}: agreed ${inr(x.cm.agreedPaise+linkedChangeCost(x.cm.id))}, allocated ${inr(sum(x.cm.allocation,a=>a.amountPaise))} · <b class="num">${x.diff>0?'+':'−'}${inr(Math.abs(x.diff))}</b> unplaced</span>${can('budget')&&!locked(e)?`<button class="btn sm" data-act="alloc-fix" data-id="${x.cm.id}">Place it</button>`:''}</div>`).join('')}</div>`+h};
act('alloc-fix',({id})=>{const cm=S.commitments.find(c=>c.id===id);const diff=allocMismatch(cm);if(!diff)return toast('Nothing to fix');const lines=cm.allocation.map(a=>({a,l:S.scopeLines.find(x=>x.id===a.scopeLineId)||{desc:'?',category:'?'}}));openModal(`${hd('Place the unallocated '+inr(Math.abs(diff)))}<form id="f-af"><p class="small">${esc(vendor(cm.vendorId).name)} is agreed at ${inr(cm.agreedPaise+linkedChangeCost(cm.id))}; the lines below add to ${inr(sum(cm.allocation,a=>a.amountPaise))}. Choose where the ${diff>0?'extra':'shortfall'} belongs. Nothing is changed silently; this is recorded on the agreement.</p>${lines.map((x,i)=>`<label class="chk"><input type="radio" name="afl" value="${i}" ${i===0?'checked':''}> ${esc(x.l.category)} · ${esc(x.l.desc)} — now ${inr(x.a.amountPaise)}</label>`).join('')}<label class="chk"><input type="radio" name="afl" value="prop"> Spread in proportion across the lines</label><label for="afw">Why</label><input id="afw" required placeholder="Agreed amount changed after the lines were set">${ft('Place')}</form>`);F('f-af').addEventListener('submit',x=>{x.preventDefault();const how=f=>f;const sel=document.querySelector('input[name=afl]:checked').value;const why=F('afw').value.trim();if(why.length<5)return toast('Say why');const before=JSON.parse(JSON.stringify(cm.allocation));if(sel==='prop'){const tot=sum(cm.allocation,a=>a.amountPaise)||1;let left=diff;cm.allocation.forEach((a,i)=>{const d=i===cm.allocation.length-1?left:Math.round(diff*a.amountPaise/tot);a.amountPaise+=d;left-=d})}else{cm.allocation[parseInt(sel)].amountPaise+=diff}cm.allocationFixes=cm.allocationFixes||[];cm.allocationFixes.push({ts:nowISO(),by:UI.userId,diff,how:sel==='prop'?'proportional':lines[parseInt(sel)].l.desc,why,before});touch(cm);audit('update','commitments',cm.id,`placed ${inr(Math.abs(diff))} unallocated: ${why}`,cm.eventId);save();closeModal();render();toast('Placed')})});
const _orderMake=ACTS['order-make'];act('order-make',ctx=>{const cm=S.commitments.find(c=>c.id===ctx.id);const d=cm?allocMismatch(cm):0;if(d)return toast(`Place the ${inr(Math.abs(d))} not on any scope line first (Scope tab) — the work order would be wrong`);return _orderMake(ctx)});

/* ---------- D. Vendor reliability ---------- */
const _vendorPerfBase=vendorPerf;vendorPerf=function(v){const p=_vendorPerfBase(v);const os=live(S.orders).filter(o=>o.vendorId===v.id&&o.sentAt&&o.acceptedAt);p.ackHours=os.length?sum(os,o=>(new Date(o.acceptedAt)-new Date(o.sentAt))/36e5)/os.length:null;p.late=p.deliveries-p.onTime;const rh=(v.rehire||[]);p.rehireYes=rh.filter(r=>r.yes).length;p.rehireNo=rh.filter(r=>!r.yes).length;p.lastNo=rh.filter(r=>!r.yes).slice(-1)[0]||null;return p};
function perfChips(v){if(!v||v.id==='v_other')return '';const p=vendorPerf(v);const comp=vendorCompliance(v);const out=[];if(p.ackHours!=null)out.push(`<span class="pill ${p.ackHours<=24?'ok':p.ackHours<=72?'warn':'bad'}" title="average time from order sent to vendor acknowledgement">acks in ${p.ackHours<1?'under an hour':Math.round(p.ackHours)+'h'}</span>`);if(p.deliveries)out.push(`<span class="pill ${p.late?'bad':'ok'}">${p.onTime}/${p.deliveries} on time</span>`);if(p.short)out.push(`<span class="pill warn">${p.short} short delivery</span>`);if(p.priceVar!=null)out.push(`<span class="pill ${p.priceVar>0?'warn':'ok'}" title="average bill vs order">bills ${p.priceVar>=0?'+':'−'}${inr(Math.abs(Math.round(p.priceVar)))}</span>`);if(p.disputes)out.push(`<span class="pill bad">${p.disputes} dispute${p.disputes>1?'s':''}</span>`);if(p.rehireYes+p.rehireNo)out.push(`<span class="pill ${p.rehireNo?'bad':'ok'}" title="${p.lastNo?esc(p.lastNo.why):''}">rehire ${p.rehireYes}/${p.rehireYes+p.rehireNo}${p.lastNo?' · last no: '+esc(p.lastNo.why.slice(0,40)):''}</span>`);if(vendorUnregistered(v))out.push(`<span class="pill warn" title="no GST input credit on this vendor's bills">unregistered · no input credit</span>`);if(!out.length)return `<span class="pill grey">no history yet</span>`;return out.join(' ')}
const _rfqCardPerf=rfqCard;rfqCard=function(e){let h=_rfqCardPerf(e);const vids=new Set();S.rfqs.filter(r=>r.eventId===e.id&&!r.voided).forEach(r=>r.vendorIds.forEach(v=>vids.add(v)));vids.forEach(vid=>{const v=vendor(vid);const key=`<td><b>${esc(v.name)}</b>`;h=h.split(key).join(key+`<div class="chips" style="margin-top:2px">${perfChips(v)}</div>`)});return h};
const _mCommitmentPerf=mCommitment;mCommitment=function(cm,asQuote){_mCommitmentPerf(cm,asQuote);const sel=F('cv');if(!sel)return;const d=document.createElement('div');d.className='chips';d.style.margin='4px 0 8px';sel.insertAdjacentElement('afterend',d);const upd=()=>{const v=S.vendors.find(x=>x.id===sel.value);d.innerHTML=v?perfChips(v):''};sel.addEventListener('change',upd);upd()};
act('rehire',({id,E,v})=>{const e=E();const vend=vendor(id);const yes=v==='yes';openModal(`${hd((yes?'Hire again: ':'Not again: ')+esc(vend.name))}<form id="f-rh"><label for="rhw">${yes?'What went well? (one line)':'What went wrong? This shows beside their next quote.'}</label><input id="rhw" required>${ft('Record')}</form>`);F('f-rh').addEventListener('submit',x=>{x.preventDefault();vend.rehire=(vend.rehire||[]).filter(r=>r.eventId!==e.id);vend.rehire.push({eventId:e.id,yes,why:F('rhw').value.trim(),by:UI.userId,at:nowISO()});touch(vend);audit('update','vendors',vend.id,(yes?'rehire: yes — ':'rehire: no — ')+F('rhw').value.trim(),e.id);save();closeModal();render()})});

/* ---------- E. Close-out → next quote ---------- */
function lineActual(l){const com=lineCommitted(l);if(com)return com;const cs=costComms(l.eventId).filter(cm=>!allocOf(cm).length&&vendor(cm.vendorId).category===l.category);return sum(cs,cm=>cm.agreedPaise+linkedChangeCost(cm.id))}
function closeoutLessons(e){const c=calc(e);const sc=scopeSummary(e);const base=e.budget&&Object.keys(e.budget).length?e.budget:(e.budgetBaseline||{});const vendors=sc.lines.map(x=>{const act_=lineActual(x.l);const who=[...new Set(costComms(e.id).filter(cm=>allocOf(cm).some(a=>a.scopeLineId===x.l.id)||(!allocOf(cm).length&&vendor(cm.vendorId).category===x.l.category)).map(cm=>vendor(cm.vendorId).name))];return {l:x.l,quoted:x.l.baselineCostPaise,actual:act_,diff:act_-x.l.baselineCostPaise,who}}).filter(x=>x.diff);const as=live(S.assignments).filter(a=>a.eventId===e.id);const otDays=sum(as,a=>Object.keys(a.otApproved||{}).filter(k=>a.otApproved[k]).length);const crew={planned:base.Crew||0,actual:c.crew,diff:c.crew-(base.Crew||0),people:as.length,otDays};const chs=live(S.changes).filter(x=>x.eventId===e.id&&chApproved(x));const leak=chs.filter(x=>x.clientPaise<x.costPaise);return {vendors,crew,leak,changes:chs,bridge:marginBridge(e,c)}}
function rateProposalsFor(e){const L=closeoutLessons(e);const out=[];L.vendors.forEach(x=>{const qty=x.l.qty||1;if(x.l.unitCostPaise==null||!x.actual)return;const from=x.l.unitCostPaise,to=Math.round(x.actual/qty);if(Math.abs(to-from)<from*0.05)return;out.push({kind:'pricebook',category:x.l.category,unit:x.l.unit,desc:x.l.desc,fromPaise:from,toPaise:to,evidence:`${e.name}: quoted ${inr(from)} per ${x.l.unit}, bought at ${inr(to)} (${x.who.join(', ')||'no vendor linked'})`,eventId:e.id,scopeLineId:x.l.id})});const tpl=(S.company.quoteTemplates||[]).find(t=>t.type===e.type);if(tpl&&L.crew.planned&&Math.abs(L.crew.diff)>=L.crew.planned*0.05){const line=tpl.lines.find(l=>l[0]==='Crew');const perGuest=line&&line[2];const to=perGuest?Math.round(L.crew.actual/(e.guests||1)):L.crew.actual;const from=line?line[3]*100:L.crew.planned;if(line)out.push({kind:'template',type:e.type,category:'Crew',unit:perGuest?'per guest':'lump sum',desc:'Crew cost on the '+tpl.name+' template',fromPaise:from,toPaise:to,evidence:`${e.name}: crew planned ${inr(L.crew.planned)}, actual ${inr(L.crew.actual)} (${L.crew.people} people, ${L.crew.otDays} overtime day${L.crew.otDays===1?'':'s'})`,eventId:e.id,scopeLineId:null})}return out}
act('propose-rates',({E})=>{const e=E();const ps=rateProposalsFor(e);let n=0;ps.forEach(p=>{if(S.rateProposals.some(x=>x.eventId===e.id&&x.scopeLineId===p.scopeLineId&&x.kind===p.kind&&x.category===p.category))return;S.rateProposals.push(stamp(Object.assign({id:uid(),status:'proposed',decidedBy:null,decidedAt:null,decisionNote:''},p)));n++});audit('create','rateProposals',e.id,n+' proposal(s) from close-out',e.id);save();render();toast(n?n+' proposal(s) queued for the owner — nothing changed yet':'Nothing new to propose (within 5% or already proposed)')});
act('proposal-decide',({id,v})=>{const p=S.rateProposals.find(x=>x.id===id);if(!isOwner())return toast('Only the owner approves rate changes');const ok=v==='approve';openModal(`${hd((ok?'Approve: ':'Decline: ')+esc(p.category))}<form id="f-pd"><p class="small">${esc(p.evidence)}</p><p class="small">${ok?(p.kind==='pricebook'?`Adds a price book entry at <b>${inr(p.toPaise)}</b> per ${esc(p.unit)} dated ${fmtShort(ev(p.eventId).startDate)}. Existing entries are kept; the next quote's hint moves because this one is newest.`:`Changes the ${esc(p.type)} template's Crew cost from ${inr(p.fromPaise)} to <b>${inr(p.toPaise)}</b>.`):'Declined proposals stay on the list, greyed, so the same lesson is not proposed twice.'}</p><label for="pdn">Note</label><input id="pdn" ${ok?'':'required'} placeholder="${ok?'optional':'why not'}">${ft(ok?'Approve':'Decline')}</form>`);F('f-pd').addEventListener('submit',x=>{x.preventDefault();p.status=ok?'approved':'declined';p.decidedBy=UI.userId;p.decidedAt=nowISO();p.decisionNote=F('pdn').value.trim();if(ok){const e=ev(p.eventId);if(p.kind==='pricebook'){const pb=stamp({id:uid(),category:p.category,unit:p.unit,desc:p.desc,ratePaise:p.toPaise,location:(e.venue||'').split(',').slice(-1)[0].trim()||'Kochi',date:e.startDate,vendorId:null,eventId:e.id,commitmentId:null,sampleSize:1,confidence:'high',validUntil:addDays(e.startDate,365),source:'close-out proposal',proposalId:p.id});S.priceBook.push(pb);p.priceBookId=pb.id}else{const tpl=(S.company.quoteTemplates||[]).find(t=>t.type===p.type);const line=tpl&&tpl.lines.find(l=>l[0]==='Crew');if(line){p.templateBefore=line[3];line[3]=Math.round(p.toPaise/100)}}}audit(ok?'approve':'decline','rateProposals',p.id,`${p.category} ${inr(p.fromPaise)} → ${inr(p.toPaise)}${p.decisionNote?': '+p.decisionNote:''}`,p.eventId);save();closeModal();render()})});
function vProposals(){const ps=S.rateProposals.slice().sort((a,b)=>(a.status==='proposed'?0:1)-(b.status==='proposed'?0:1)||b.createdAt.localeCompare(a.createdAt));const open=ps.filter(p=>p.status==='proposed');return `${topbar()}<div class="eyebrow">Each event improves the next quote</div><h1>Next-quote proposals</h1><div class="small muted" style="margin:4px 0 10px">Close-out finds where a quoted rate and the bought rate disagree by 5% or more and proposes a price-book change. Nothing is applied until the owner approves it, one line at a time; declined ones stay here so they are not proposed again. ${isOwner()?'':'<b>Only the owner decides.</b>'}</div>${ps.length?`<div class="card"><div class="scroll"><table><thead><tr><th>Category</th><th class="r">Quoted</th><th class="r">Bought</th><th>Evidence</th><th>Status</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr style="${p.status!=='proposed'?'opacity:.6':''}"><td><b>${esc(p.category)}</b><div class="meta">${p.kind==='template'?'quote template':'price book'} · per ${esc(p.unit)}</div></td><td class="r num">${inr(p.fromPaise)}</td><td class="r num" style="color:${p.toPaise>p.fromPaise?'var(--bad)':'var(--ok)'}">${inr(p.toPaise)}</td><td class="small">${esc(p.evidence)}</td><td><span class="pill ${p.status==='approved'?'ok':p.status==='declined'?'grey':'warn'}">${p.status}</span>${p.decidedAt?`<div class="meta">${esc(user(p.decidedBy).name)} · ${fmtShort(p.decidedAt.slice(0,10))}${p.decisionNote?' · '+esc(p.decisionNote):''}</div>`:''}</td><td>${p.status==='proposed'&&isOwner()?`<div class="row" style="gap:4px"><button class="btn sm pri" data-act="proposal-decide" data-id="${p.id}" data-v="approve">Approve</button><button class="btn sm" data-act="proposal-decide" data-id="${p.id}" data-v="decline">Decline</button></div>`:''}</td></tr>`).join('')}</tbody></table></div></div>`:`<div class="card"><div class="empty">No proposals yet. Close an event, then press <b>Propose next-quote changes</b> on its Close-out tab.</div></div>`}`}
addPage('proposals','Next quote',vProposals,()=>can('profit'),()=>{const n=S.rateProposals.filter(p=>p.status==='proposed').length;return n||''});
NAV_GROUPS.find(g=>g[0]==='Money')[1].push('proposals');
const _tabCloseLearn=tabClose;tabClose=function(e,c){let h=_tabCloseLearn(e,c);if(!can('profit')||stageIdx(e.stage)<5)return h;const L=closeoutLessons(e);const mine=S.rateProposals.filter(p=>p.eventId===e.id);const vs=[...new Set(costComms(e.id).map(cm=>cm.vendorId))].map(id=>vendor(id)).filter(v=>v&&v.id!=='v_other');return h+`<div class="card" style="margin-top:12px"><h3>Where the margin went — and what the next quote should learn</h3><div class="small muted">Vendor overruns and staff hours against what was quoted. Each lesson becomes a proposal the owner approves; no rate is overwritten silently.</div><div class="scroll" style="margin-top:6px"><table><thead><tr><th>Line</th><th class="r">Quoted cost</th><th class="r">Bought / spent</th><th class="r">Lost (−) / kept (+)</th><th>Who</th></tr></thead><tbody>${L.vendors.map(x=>`<tr><td>${esc(x.l.category)} · ${esc(x.l.desc)}</td><td class="r num">${inr(x.quoted)}</td><td class="r num">${inr(x.actual)}</td><td class="r num" style="color:${x.diff>0?'var(--bad)':'var(--ok)'}">${x.diff>0?'−':'+'}${inr(Math.abs(x.diff))}</td><td class="small">${esc(x.who.join(', '))}</td></tr>`).join('')}<tr><td>Crew · ${L.crew.people} ${L.crew.people===1?'person':'people'}${L.crew.otDays?', '+L.crew.otDays+' overtime day'+(L.crew.otDays===1?'':'s'):''}</td><td class="r num">${inr(L.crew.planned)}</td><td class="r num">${inr(L.crew.actual)}</td><td class="r num" style="color:${L.crew.diff>0?'var(--bad)':'var(--ok)'}">${L.crew.diff>0?'−':'+'}${inr(Math.abs(L.crew.diff))}</td><td class="small">${L.crew.otDays?'overtime approved':''}</td></tr>${L.leak.map(x=>`<tr><td>Change · ${esc(x.desc)}</td><td class="r num">${inr(x.clientPaise)} priced</td><td class="r num">${inr(x.costPaise)} cost</td><td class="r num" style="color:var(--bad)">−${inr(x.costPaise-x.clientPaise)}</td><td class="small">priced below cost</td></tr>`).join('')}</tbody></table></div><div class="row" style="gap:6px;margin-top:10px;flex-wrap:wrap"><button class="btn sm pri" data-act="propose-rates">Propose next-quote changes</button>${mine.length?`<a class="btn sm" href="#proposals">${mine.filter(p=>p.status==='proposed').length} waiting · ${mine.filter(p=>p.status==='approved').length} approved · ${mine.filter(p=>p.status==='declined').length} declined</a>`:''}</div></div><div class="card" style="margin-top:12px"><h3>Hire again?</h3><div class="small muted">One answer per vendor per event. It shows beside their next quote, so the planner comparing RFQs sees it without asking around.</div>${vs.map(v=>{const r=(v.rehire||[]).find(x=>x.eventId===e.id);return `<div class="row between" style="margin-top:6px"><span><b>${esc(v.name)}</b> <span class="muted small">${esc(v.category)}</span> ${r?`<span class="pill ${r.yes?'ok':'bad'}">${r.yes?'yes':'no'}</span> <span class="small">${esc(r.why)}</span>`:''}</span>${can('vendors')?`<span class="row" style="gap:4px"><button class="btn sm" data-act="rehire" data-id="${v.id}" data-v="yes">Yes</button><button class="btn sm" data-act="rehire" data-id="${v.id}" data-v="no">No</button></span>`:''}</div>`}).join('')||'<div class="empty">No vendors on this event.</div>'}</div>`};

/* ---------- F. Cash handling ---------- */
function cashVoucher(kind,amountPaise,o){const r=cashRules();r.voucherSeq=(r.voucherSeq||0)+1;const v=stamp(Object.assign({id:uid(),no:r.voucherPrefix+String(r.voucherSeq).padStart(3,'0'),kind,amountPaise,date:todayStr()},o));S.cashVouchers.push(v);return v}
function cashBook(){const r=cashRules();const rows=[];live(S.receipts).filter(x=>x.mode==='cash').forEach(x=>rows.push({date:x.date,inPaise:x.amountPaise,outPaise:0,what:'Client receipt · '+(ev(x.eventId)||{}).name,ref:'receipt:'+x.id,eventId:x.eventId,flag:x.s269Flag}));S.ticketSales.filter(x=>x.status==='paid'&&x.mode==='cash').forEach(x=>rows.push({date:x.date,inPaise:x.amountPaise,outPaise:0,what:'Ticket at the door · '+(ev(x.eventId)||{}).name,ref:'ticket:'+x.id,eventId:x.eventId}));live(S.payments).filter(x=>x.mode==='cash').forEach(x=>rows.push({date:x.date,inPaise:x.kind==='refund'?Math.abs(x.amountPaise):0,outPaise:x.kind==='refund'?0:x.amountPaise-(x.tdsPaise||0),what:(x.kind==='refund'?'Vendor refund · ':'Vendor payment · ')+vendor((S.commitments.find(c=>c.id===x.commitmentId)||{}).vendorId).name,ref:'payment:'+x.id,eventId:x.eventId,flag:x.s40a3Flag}));live(S.settlements).filter(x=>x.mode==='cash').forEach(x=>rows.push({date:x.date,inPaise:0,outPaise:x.amountPaise,what:'Reimbursement · '+user(x.userId).name,ref:'settlement:'+x.id}));live(S.crewPayments||[]).filter(x=>x.mode==='cash').forEach(x=>rows.push({date:x.date,inPaise:0,outPaise:x.amountPaise,what:'Crew pay',ref:'crewpay:'+x.id,eventId:x.eventId}));live(S.cashMoves).forEach(x=>rows.push({date:x.date,inPaise:x.kind==='withdrawal'?x.amountPaise:0,outPaise:x.kind==='deposit'?x.amountPaise:0,what:(x.kind==='deposit'?'Deposited to bank':'Withdrawn from bank')+(x.ref?' · '+x.ref:''),ref:'move:'+x.id}));rows.sort((a,b)=>a.date.localeCompare(b.date)||a.ref.localeCompare(b.ref));let bal=r.openingPaise||0;rows.forEach(x=>{bal+=x.inPaise-x.outPaise;x.balPaise=bal});return {rows,opening:r.openingPaise||0,balance:bal,in:sum(rows,x=>x.inPaise),out:sum(rows,x=>x.outPaise)}}
function vCashbook(){const cb=cashBook();const r=cashRules();const vs=S.cashVouchers.slice().reverse();return `${topbar()}<div class="eyebrow">Every rupee of cash, on the books</div><h1>Cash book</h1><div class="small muted" style="margin:4px 0 10px">Cash receipts and cash payments recorded anywhere in the app land here automatically, with a numbered voucher. GST and income apply to cash exactly as to bank money. Bank reconciliation leaves cash out, so this is the one place cash in hand is tracked. Limits below are the company's settings — <b>verify with your CA</b>.</div><div class="grid g4" style="margin-bottom:12px">${stat('Cash in hand',inr(cb.balance),'opening '+inr(cb.opening)+' on '+fmtShort(r.openingDate))}${stat('Cash in',inr(cb.in),cb.rows.filter(x=>x.inPaise).length+' entries')}${stat('Cash out',inr(cb.out),cb.rows.filter(x=>x.outPaise).length+' entries')}${stat('Flagged',cb.rows.filter(x=>x.flag).length,'269ST / 40A(3) acknowledgements')}</div>${cb.balance<0?`<div class="alert" style="margin-bottom:12px"><h3>Cash in hand is negative</h3><div class="small">More cash was paid out than was ever recorded coming in. Either a cash receipt or a bank withdrawal is missing. Record it — do not adjust the balance.</div></div>`:''}<div class="row" style="gap:6px;margin-bottom:12px;flex-wrap:wrap">${can('client')?`<button class="btn sm" data-act="cash-move" data-v="deposit">Deposited cash to bank</button><button class="btn sm" data-act="cash-move" data-v="withdrawal">Withdrew cash from bank</button>`:''}<button class="btn sm" data-act="cash-csv">Export cash book (CSV)</button></div><div class="card"><div class="scroll"><table><thead><tr><th>Date</th><th>What</th><th class="r">In</th><th class="r">Out</th><th class="r">Balance</th><th></th></tr></thead><tbody>${cb.rows.length?cb.rows.map(x=>`<tr><td class="num">${fmtShort(x.date)}</td><td>${esc(x.what)}<div class="meta">${esc(x.ref)}</div></td><td class="r num">${x.inPaise?inr(x.inPaise):''}</td><td class="r num">${x.outPaise?inr(x.outPaise):''}</td><td class="r num" style="${x.balPaise<0?'color:var(--bad)':''}">${inr(x.balPaise)}</td><td>${x.flag?'<span class="pill warn">flagged</span>':''}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No cash movements recorded.</td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:12px"><h3>Cash vouchers (${vs.length})</h3><div class="small muted">One per cash receipt or cash payment, numbered in order. Print or download when the other party wants a signed copy.</div><div class="scroll"><table><thead><tr><th>No.</th><th>Date</th><th>Kind</th><th>Party</th><th class="r">Amount</th><th></th></tr></thead><tbody>${vs.map(v=>`<tr><td class="num">${esc(v.no)}</td><td class="num">${fmtShort(v.date)}</td><td>${v.kind}</td><td>${esc(v.party||'')}<div class="meta">${esc(v.desc||'')}</div></td><td class="r num">${inr(v.amountPaise)}</td><td><button class="btn sm" data-act="voucher-pdf" data-id="${v.id}">PDF</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">None yet.</td></tr>'}</tbody></table></div></div>`}
addPage('cashbook','Cash book',vCashbook,()=>can('client')||can('books'),()=>{const b=cashBook().balance;return b<0?'!':''});
NAV_GROUPS.find(g=>g[0]==='Money')[1].splice(2,0,'cashbook');
act('cash-move',({v})=>{openModal(`${hd(v==='deposit'?'Cash deposited to bank':'Cash withdrawn from bank')}<form id="f-cm"><div class="two"><div><label for="cma">Amount (₹)</label><input id="cma" inputmode="decimal" required></div><div><label for="cmd">Date</label><input id="cmd" type="date" required value="${todayStr()}"></div></div><label for="cmr">Bank reference / slip no.</label><input id="cmr">${ft('Record')}</form>`);F('f-cm').addEventListener('submit',x=>{x.preventDefault();const a=toPaise(F('cma').value);if(!a||a<=0)return toast('Enter an amount');const m=stamp({id:uid(),kind:v,amountPaise:a,date:F('cmd').value,ref:F('cmr').value.trim()});S.cashMoves.push(m);audit('create','cashMoves',m.id,`${v} ${inr(a)}`);save();closeModal();render()})});
act('cash-csv',()=>{const cb=cashBook();const csv=[['date','what','ref','in','out','balance','flag']].concat(cb.rows.map(x=>[x.date,x.what,x.ref,x.inPaise/100,x.outPaise/100,x.balPaise/100,x.flag?'yes':''])).map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n');downloadBlob('cash-book.csv',new Blob([csv],{type:'text/csv'}))});
act('voucher-pdf',({id})=>{const v=S.cashVouchers.find(x=>x.id===id);downloadBlob('cash-voucher-'+v.no.replace(/\W+/g,'_')+'.pdf',makePdf('Cash voucher',[{t:`CASH VOUCHER ${v.no}`,b:true,s:12},{t:`Date: ${fmtDate(v.date)}`},{t:`${v.kind==='receipt'?'Received from':'Paid to'}: ${v.party||''}`},{t:`For: ${v.desc||''}`},{t:`Amount: Rs. ${(v.amountPaise/100).toFixed(2)}`,b:true},{t:`Reference: ${v.ref||''}`},{t:''},{t:'Signature of receiver: ____________________'},{t:'Prepared by: '+(user(v.createdBy)||{}).name}]))});
/* client receipts in cash: 269ST */
const _mReceiptCash=mReceipt;mReceipt=function(m){_mReceiptCash(m);const f=document.querySelector('.modal form');if(!f)return;const e=ev(m.eventId);const box=document.createElement('div');box.id='rcashbox';f.insertBefore(box,f.querySelector('.ft'));guardSubmit(f,evt=>{if(F('rm').value!=='cash')return;const amt=toPaise(F('ra').value)||0;const r=cashRules();const sofar=sum(live(S.receipts).filter(x=>x.eventId===e.id&&x.mode==='cash'),x=>x.amountPaise);if(sofar+amt<r.s269Paise)return;if(!F('rcashack')){F('rcashbox').innerHTML=`<div class="alert" style="margin:6px 0"><h3>Cash of ${inr(r.s269Paise)} or more for one event</h3><p class="small">Section 269ST: receiving this much in cash from one person for one occasion is prohibited for the receiver, with a penalty equal to the amount (${sofar?'already '+inr(sofar)+' in cash on this event; ':''}this makes ${inr(sofar+amt)}). The receipt is recorded in full either way — this app never keeps money off the books. Ask the client to pay the balance by bank or UPI; if the cash is already in hand, record it and tell your CA.</p><label class="chk"><input type="checkbox" id="rcashack"> Record it anyway — I understand the exposure</label></div>`;F('rcashack').focus();return blockSubmit(evt)}if(!F('rcashack').checked){toast('Tick the acknowledgement or change the payment mode');return blockSubmit(evt)}afterSave(()=>{const x=S.receipts[S.receipts.length-1];if(x&&x.milestoneId===m.id&&x.mode==='cash'){x.s269Flag=true;audit('flag','receipts',x.id,'cash at or above the 269ST limit for this event, acknowledged',e.id);save()}})});
  /* voucher for every cash receipt, flagged or not */
  guardSubmit(f,()=>{if(F('rm').value!=='cash')return;afterSave(()=>{const x=S.receipts[S.receipts.length-1];if(x&&x.milestoneId===m.id&&x.mode==='cash'&&!S.cashVouchers.some(v=>v.ref==='receipt:'+x.id)){cashVoucher('receipt',x.amountPaise,{eventId:e.id,ref:'receipt:'+x.id,party:e.client,desc:'Client receipt · '+m.desc});save()}})})};
/* reimbursements in cash: voucher */
const _mSettleCash=mSettle;mSettle=function(userId){_mSettleCash(userId);const f=document.querySelector('.modal form');if(!f||!F('sm'))return;guardSubmit(f,()=>{if(F('sm').value!=='cash')return;afterSave(()=>{const x=S.settlements[S.settlements.length-1];if(x&&x.userId===userId&&x.mode==='cash'&&!S.cashVouchers.some(v=>v.ref==='settlement:'+x.id)){cashVoucher('payment',x.amountPaise,{ref:'settlement:'+x.id,party:user(userId).name,desc:'Expense reimbursement'});save()}})})};
/* settings card */
settingsCard(()=>{const r=cashRules();return `<div class="card"><div class="row between"><h2>Cash handling</h2>${can('settings')?'<button class="btn sm" data-act="cash-rules">Edit</button>':''}</div><div class="small muted">Cash is a legal way to pay and is recorded like any other. These limits only decide when the app warns. <b>Verify with your CA</b>; the defaults are the statutory figures as understood at build time, not advice.</div><div class="kv small" style="margin-top:6px"><b>Section 269ST</b><span>warn at ${inr(r.s269Paise)} cash received from one client for one event (receiver's penalty = amount)</span><b>Section 40A(3)</b><span>warn above ${inr(r.s40a3Paise)} cash paid to one vendor in a day (expense may be disallowed)</span><b>Vouchers</b><span>${esc(r.voucherPrefix)} · next no. ${(r.voucherSeq||0)+1}</span><b>Opening cash</b><span>${inr(r.openingPaise||0)} on ${fmtShort(r.openingDate)}</span><b>Unregistered vendors</b><span>no GST input credit on their bills; their quotes are compared without a tax line; reverse charge is for your CA to decide</span></div></div>`});
act('cash-rules',()=>{if(!can('settings'))return;const r=cashRules();openModal(`${hd('Cash handling rules')}<form id="f-cr"><div class="two"><div><label for="cr1">269ST limit (₹)</label><input id="cr1" inputmode="decimal" value="${r.s269Paise/100}"></div><div><label for="cr2">40A(3) daily limit (₹)</label><input id="cr2" inputmode="decimal" value="${r.s40a3Paise/100}"></div></div><div class="two"><div><label for="cr3">Voucher prefix</label><input id="cr3" value="${esc(r.voucherPrefix)}"></div><div><label for="cr4">Opening cash (₹)</label><input id="cr4" inputmode="decimal" value="${(r.openingPaise||0)/100}"></div></div><label for="cr5">Opening date</label><input id="cr5" type="date" value="${r.openingDate}"><p class="small muted">Limits are warnings, not blocks: money that was received or paid is always recorded.</p>${ft('Save')}</form>`);F('f-cr').addEventListener('submit',x=>{x.preventDefault();Object.assign(r,{s269Paise:toPaise(F('cr1').value)||r.s269Paise,s40a3Paise:toPaise(F('cr2').value)||r.s40a3Paise,voucherPrefix:F('cr3').value.trim()||r.voucherPrefix,openingPaise:toPaise(F('cr4').value)||0,openingDate:F('cr5').value||r.openingDate});audit('update','company','cashRules','cash rules changed');save();closeModal();render()})});
/* unregistered vendors: an explicit status on the vendor (a blank GSTIN field is "unknown", not "unregistered"); RFQ normalisation has no tax line; commitment row says so */
const vendorUnregistered=v=>!!v&&!(v.compliance||{}).gstin&&(v.compliance||{}).gstStatus==='unregistered';
const _vcModal=ACTS['vendor-compliance'];act('vendor-compliance',ctx=>{_vcModal(ctx);const g=F('vcg');if(!g)return;const v=S.vendors.find(x=>x.id===ctx.id);const st=(v.compliance||{}).gstStatus||'';g.insertAdjacentHTML('afterend',`<label for="vcgs">GST status</label><select id="vcgs"><option value="" ${st===''?'selected':''}>Unknown — ask the vendor</option><option value="registered" ${st==='registered'?'selected':''}>Registered (GSTIN above)</option><option value="unregistered" ${st==='unregistered'?'selected':''}>Unregistered — no input credit on their bills</option></select><div class="help">Unregistered vendors cannot charge GST. Whether reverse charge applies to what they supply is for your CA.</div>`);const f=g.closest('form');guardSubmit(f,()=>{const val=F('vcgs').value;afterSave(()=>{v.compliance=v.compliance||{};if(v.compliance.gstStatus!==val){v.compliance.gstStatus=val;touch(v);audit('update','vendors',v.id,'GST status: '+(val||'unknown'));save();render()}})})});
const _rfqNormBase=rfqNormalized;rfqNormalized=function(r,resp){const n=_rfqNormBase(r,resp);const v=vendor(resp.vendorId);if(v&&vendorUnregistered(v)&&!resp.taxIncluded){n.gross-=n.tax;n.tax=0;n.unregistered=true}return n};
VENDOR_ROW_EXT.push((cm,e)=>{const v=vendor(cm.vendorId);if(!v||cm.voided||!seesMoney())return '';if(!vendorUnregistered(v))return '';return `<div class="meta">Unregistered for GST: GST on this vendor's bills cannot be claimed as input credit; cash payments above ${inr(cashRules().s40a3Paise)} a day are flagged.</div>`});

/* ---------- Exceptions ---------- */
const _exceptionsBase=exceptions;exceptions=function(){const out=_exceptionsBase();S.events.filter(isLive).forEach(e=>{const owner=user(e.plannerId).name;mismatchesOf(e.id).forEach(x=>out.push({sev:'bad',kind:'Allocation mismatch',e,owner,txt:`${vendor(x.cm.vendorId).name}: ${inr(Math.abs(x.diff))} not on any scope line`,src:'Scope & forecast',tab:'scope'}));agreedComms(e.id).forEach(cm=>{const k=commCalc(cm);if(k.retention>0)out.push({sev:'warn',kind:'Retention held',e,owner,txt:`${vendor(cm.vendorId).name}: ${inr(k.retention)} held; payable ${inr(k.payable)}`,src:'Vendors',tab:'vendors'});const over=live(S.payments).filter(p=>p.commitmentId===cm.id&&p.retentionOverride);if(over.length)out.push({sev:'bad',kind:'Retention paid out',e,owner,txt:`${vendor(cm.vendorId).name}: ${over.map(p=>inr(p.amountPaise)+' — '+p.retentionOverride).join('; ')}`,src:'Vendors',tab:'vendors'})});ticketDrift(e).forEach(x=>out.push({sev:'bad',kind:'Ticket count drift',e,owner,txt:`${x.t.name}: ${x.t.sold||0} sold vs ${x.active} delegates${x.noSale.length?'; '+x.noSale.length+' without a sale':''}`,src:'Delegates & ticketing',tab:'delegates'}));const pend=S.ticketSales.filter(s=>s.eventId===e.id&&s.status==='pending'&&daysUntil(s.date)<=-7);if(pend.length)out.push({sev:'warn',kind:'Tickets unpaid',e,owner,txt:`${pend.length} sale(s) pending over a week · ${inr(sum(pend,s=>s.amountPaise))}`,src:'Delegates & ticketing',tab:'delegates'});live(S.receipts).filter(r=>r.eventId===e.id&&r.s269Flag).forEach(r=>out.push({sev:'bad',kind:'Cash above 269ST',e,owner,txt:`${inr(r.amountPaise)} cash on ${fmtShort(r.date)} — tell the CA`,src:'Client money',tab:'client'}))});live(S.payments).filter(p=>p.s40a3Flag).forEach(p=>{const e=ev(p.eventId);if(e)out.push({sev:'warn',kind:'Cash above 40A(3)',e,owner:user(e.plannerId).name,txt:`${inr(p.amountPaise)} cash on ${fmtShort(p.date)} to ${vendor((S.commitments.find(c=>c.id===p.commitmentId)||{}).vendorId).name}`,src:'Vendors',tab:'vendors'})});const cb=cashBook();if(cb.balance<0&&S.events[0])out.push({sev:'bad',kind:'Cash book negative',e:S.events.find(isLive)||S.events[0],owner:'Owner',txt:`cash in hand ${inr(cb.balance)} — a receipt or bank withdrawal is missing`,src:'Cash book',tab:null});return out.sort((a,b)=>(a.sev==='bad'?0:1)-(b.sev==='bad'?0:1))};

/* ---------- Sample data ---------- */
SEED_EXT.push((S0,h)=>{S0.company.cashRules=defaultCashRules();S0.company.cashRules.voucherSeq=2;S0.company.cashRules.openingPaise=1500000;S0.company.cashRules.openingDate='2026-04-01';(S0.vendors||[]).forEach(v=>{v.rehire=v.rehire||[]});const v7=S0.vendors.find(v=>v.id==='v7');if(v7){v7.compliance=v7.compliance||{docs:[]};v7.compliance.gstStatus='unregistered'}
  // retention on the disputed AV order (e2) stays as the review found it — now it reduces what is payable
  // allocation mismatch sample: TechNova AV agreement allocated short by ₹15,000 after a re-negotiation
  const c9=S0.commitments.find(c=>c.id==='c9');const avLine=S0.scopeLines.find(l=>l.eventId==='e2'&&l.category==='Music');if(c9&&avLine){c9.scopeLineIds=[avLine.id];c9.allocation=[{scopeLineId:avLine.id,amountPaise:c9.agreedPaise-1500000}]}
  // cash on the books: the priest was paid ₹15,000 in cash on the Menon housewarming (voucher), and a summit ticket was sold for cash at the desk (voucher)
  const p8=S0.payments.find(p=>p.id==='p8');if(p8)S0.cashVouchers.push(h.stamp({id:'cv1',no:'CV/26-27/001',kind:'payment',amountPaise:p8.amountPaise,date:p8.date,eventId:'e3',ref:'payment:'+p8.id,party:'Sharma Ji Pandit',desc:'Vendor payment · Griha pravesh pooja'},'u3',h.t('2026-08-22T09:00')));
  S0.cashMoves.push(h.stamp({id:'cm1',kind:'withdrawal',amountPaise:2000000,date:'2026-08-20',ref:'ATM, for event-day cash'},'u1',h.t('2026-08-20')));
  // link the housewarming's agreements to their scope lines so close-out reads bought vs quoted per line
  [['c13','Décor'],['c14','Catering'],['c15','Priest']].forEach(([cid,cat])=>{const cm=S0.commitments.find(c=>c.id===cid);const l=S0.scopeLines.find(x=>x.eventId==='e3'&&x.category===cat);if(cm&&l){cm.scopeLineIds=[l.id];cm.allocation=[{scopeLineId:l.id,amountPaise:cm.agreedPaise}]}});
  // rehire answers from the closed housewarming
  const rh=(vid,yes,why)=>{const v=S0.vendors.find(x=>x.id===vid);if(v)v.rehire.push({eventId:'e3',yes,why,by:'u1',at:h.t('2026-08-30')})};rh('v2',true,'Lunch on time, no plate shortfall');rh('v7',true,'Punctual');rh('v1',false,'Entrance florals wilted by noon; replaced only after three calls');
  // one proposal already decided, to show the trail
  S0.rateProposals.push(h.stamp({id:'rp0',kind:'pricebook',category:'Décor',unit:'lump sum',desc:'Floral décor, entrance',fromPaise:14000000,toPaise:15000000,evidence:'Menon housewarming: quoted ₹1,40,000 lump sum, bought at ₹1,50,000 (XYZ Decorators)',eventId:'e3',scopeLineId:(S0.scopeLines.find(l=>l.eventId==='e3'&&l.category==='Décor')||{}).id||null,status:'declined',decidedBy:'u1',decidedAt:h.t('2026-09-01'),decisionNote:'One-off: entrance was redone after the wilting; the baseline rate stands'},'u1',h.t('2026-08-30')));
  // door sale on the summit: a delegate added at the desk, paid in cash — the exact case the review found
  const e7=S0.events.find(e=>e.id==='e7');const tt=S0.ticketTypes.find(t=>t.eventId==='e7'&&t.pricePaise>0);if(e7&&tt){const d=h.stamp({id:'d_door',eventId:'e7',name:'Rahul Varma',email:'rahul.varma@example.in',company:'Walk-in',ticketTypeId:tt.id,status:'confirmed',consent:true,paidPaise:tt.pricePaise,token:'dl_d_door',source:'manual',note:'Registered at the desk, paid cash'},'u1',h.t(addDays(h.TD,-1)));S0.delegates.push(d);tt.sold=(tt.sold||0)+1;S0.ticketSales.push(h.stamp({id:'ts_door',eventId:'e7',delegateId:'d_door',ticketTypeId:tt.id,amountPaise:tt.pricePaise,status:'paid',date:addDays(h.TD,-1),paidAt:h.t(addDays(h.TD,-1)),mode:'cash',ref:'',source:'manual'},'u1',h.t(addDays(h.TD,-1))));S0.cashVouchers.push(h.stamp({id:'cv2',no:'CV/26-27/002',kind:'receipt',amountPaise:tt.pricePaise,date:addDays(h.TD,-1),eventId:'e7',ref:'ticket:ts_door',party:'Rahul Varma',desc:'Ticket at the door · '+tt.name},'u1',h.t(addDays(h.TD,-1))));if(e7.ticketRevenueOwner==='company')S0.otherIncome.push(h.stamp({id:'oi_door',eventId:'e7',vendorId:null,desc:'Ticket: Rahul Varma',amountPaise:tt.pricePaise,date:addDays(h.TD,-1),laneRef:'ts_door'},'u1',h.t(addDays(h.TD,-1))))}
  // delegates on priced classes with no money and no sale: mark complimentary so the invariant is honest about them
  S0.delegates.filter(d=>d.eventId==='e7'&&d.status!=='cancelled').forEach(d=>{const t=S0.ticketTypes.find(x=>x.id===d.ticketTypeId);if(t&&t.pricePaise>0&&!S0.ticketSales.some(s=>s.delegateId===d.id))d.comp=true});
});

